parameters.jsCode:
// El nodo AI Agent devuelve 'output'; la cadena simple devolvia 'text'.
// Se leen los dos para que el ejemplo no dependa de cual se use.
function leer(nodo) {
  try {
    const j = $(nodo).first().json;
    const v = (j.output !== undefined && j.output !== null) ? j.output : j.text;
    return (v === undefined || v === null) ? '' : String(v).trim();
  } catch (e) { return ''; }
}

const caso     = $('El caso').first().json.caso;
const borrador = leer('Paso 1 - ChatGPT redacta el borrador');
const criticas = leer('Paso 2 - Llama revisa y critica');

// Ojo: un nodo DESACTIVADO en n8n no se saltea, deja pasar los datos del anterior.
// Si lo que llega del paso 3 es identico a las criticas, Claude no corrio.
const crudo = leer('Paso 3 - Claude escribe la version final');
const claudeCorrio = crudo !== '' && crudo !== criticas;
const final = claudeCorrio ? crudo : null;

const etapas = [
  { paso: '1. Redacta',   quien: 'ChatGPT gpt-4o-mini', donde: 'Nube - OpenAI',            texto: borrador },
  { paso: '2. Critica',   quien: 'Llama 3.1 8B',        donde: 'Local - nuestro servidor', texto: criticas },
  { paso: '3. Reescribe', quien: 'Claude',              donde: 'Nube - Anthropic',
    texto: final || 'PENDIENTE: falta cargar la clave de API de Anthropic y activar los dos nodos de Claude' },
];

const salida = etapas.map(e => ({
  json: { paso: e.paso, quien: e.quien, donde: e.donde,
          palabras: e.texto ? e.texto.split(/\s+/).length : 0, texto: e.texto }
}));

salida.push({ json: {
  paso: 'RESULTADO', quien: claudeCorrio ? 'Las tres juntas' : '-',
  donde: '-', palabras: final ? final.split(/\s+/).length : 0,
  texto: final || 'Todavia no hay resultado final: Claude es el que cierra y esta desactivado.',
  caso } });

return salida;
